"import json\nimport logging\nimport sys\nfrom pathlib import Path\n\n# Add root directory to path for imports\nROOT_DIR = Path(r\"c:\\Users\\a50057663\\Desktop\\Automações\\SmartEvents\")\nsys.path.insert(0, str(ROOT_DIR))\n\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s [%(levelname)s] %(name)s: %(message)s\")\n\nfrom core.collector import HttpCollector\n\ndef main():\n    event_path = ROOT_DIR / \"sample_event.json\"\n    if not event_path.exists():\n        print(f\"sample_event.json not found at {event_path}\")\n        return\n\n    with open(event_path, encoding=\"utf-8\") as f:\n        event_config = json.load(f)\n\n    # Initialize HttpCollector\n    base_url = event_config.get(\"oss\", {}).get(\"base_url\")\n    print(f\"Initializing HttpCollector with base_url={base_url}\")\n    collector = HttpCollector(event_config, base_url)\n\n    # Collect KPIs\n    print(\"Collecting KPIs...\")\n    try:\n        kpis = collector.collect_kpis()\n        print(f\"Collected {len(kpis)} KPI measurements.\")\n        if kpis:\n            print(\"Sample KPI:\")\n            print(json.dumps(kpis[0], indent=2))\n    except Exception as e:\n        print(f\"Error collecting KPIs: {e}\")\n\n    # Collect VIPs\n    print(\"Collecting VIPs...\")\n    try:\n        vips = collector.collect_vips()\n        print(f\"Collected {len(vips)} VIP measurements.\")\n        if vips:\n            print(\"Sample VIP:\")\n            print(json.dumps(vips[0], indent=2))\n    except Exception as e:\n        print(f\"Error collecting VIPs: {e}\")\n\nif __name__ == \"__main__\":\n    main()\n"